```c++
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <cmath>
using namespace std;
int main() {
    // Open the CSV file
    ifstream file("data.csv");
    // Check if the file was opened successfully
    if (!file.is_open()) {
        cerr << "Error opening file" << endl;
        return 1;
    }
    // Read the header line
    string header;
    getline(file, header);
    // Find the index of the feature we want to analyze
    string feature_name = "motor_current"; // Change this to the name of the feature you want to analyze
    int feature_index = -1;
    stringstream ss(header);
    string token;
    int i = 0;
    while (getline(ss, token, ',')) {
        if (token == feature_name) {
            feature_index = i;
            break;
        }
        i++;
    }
    if (feature_index == -1) {
        cerr << "Feature not found in header" << endl;
        return 1;
    }
    // Read the data and calculate the mean and standard deviation
    vector<double> values;
    double sum = 0;
    double sum_sq = 0;
    int count = 0;
    string line;
    while (getline(file, line)) {
        stringstream ss(line);
        i = 0;
        while (getline(ss, token, ',')) {
            if (i == feature_index) {
                double value = stod(token);
                values.push_back(value);
                sum += value;
                sum_sq += value * value;
                count++;
                break;
            }
            i++;
        }
    }
    double mean = sum / count;
    double variance = (sum_sq / count) - (mean * mean);
    double stddev = sqrt(variance);
    // Print the results
    cout << "Mean " << feature_name << ": " << mean << endl;
    cout << "Standard deviation " << feature_name << ": " << stddev << endl;
    return 0;
