    mascot_with_text = insertText(mascot, [10 10], names{i}, 'FontSize', 20, 'BoxColor', 'green', 'BoxOpacity', 0.8);
    mascot_with_text = insertText(mascot_with_text, [10 50], messages{i}, 'FontSize', 16, 'BoxColor', 'green', 'BoxOpacity', 0.8);

