vector<House> readData(string filename) {
    vector<House> data;
    ifstream file(filename);
    if (file.is_open()) {
        string line;
        while (getline(file, line)) {
            House house;
            sscanf(line.c_str(), "%lf,%d,%d,%[^,],%d,%lf", &house.squareFootage, &house.numBedrooms, &house.numBathrooms, &house.location[0], &house.age, &house.price);
            data.push_back(house);
        }
        file.close();
    }
    return data;
}
// Define a function to normalize the features
void normalizeFeatures(vector<House>& data) {
    double maxSquareFootage = 0, maxAge = 0, maxPrice = 0;
    int maxNumBedrooms = 0, maxNumBathrooms = 0;
    for (int i = 0; i < data.size(); i++) {
        if (data[i].squareFootage > maxSquareFootage) {
            maxSquareFootage = data[i].squareFootage;
        }
        if (data[i].numBedrooms > maxNumBedrooms) {
            maxNumBedrooms = data[i].numBedrooms;
        }
        if (data[i].numBathrooms > maxNumBathrooms) {
            maxNumBathrooms = data[i].numBathrooms;
        }
        if (data[i].age > maxAge) {
            maxAge = data[i].age;
        }
        if (data[i].price > maxPrice) {
            maxPrice = data[i].price;
        }
    }
    for (int i = 0; i < data.size(); i++) {
        data[i].squareFootage /= maxSquareFootage;
        data[i].numBedrooms /= maxNumBedrooms;
        data[i].numBathrooms /= maxNumBathrooms;
        data[i].age /= maxAge;
        data[i].price /= maxPrice;
    }
}
// Define a function to perform linear regression
double linearRegression(vector<House>& data, double squareFootage, int numBedrooms, int numBathrooms, string location, int age) {
    double sumX1 = 0, sumX2 = 0, sumX3 = 0, sumX4 = 0, sumX5 = 0, sumY = 0, sumX1Y = 0, sumX2Y = 0, sumX3Y = 0, sumX4Y = 0, sumX5Y = 0;
    int n = data.size();
    for (int i = 0; i < n; i++) {
        sumX1 += data[i].squareFootage;
        sumX2 += data[i].numBedrooms;
        sumX3 += data[i].numBathrooms;
        sumX4 += (data[i].location == location) ? 1 : 0;
        sumX5 += data[i].age;
        sumY += data[i].price;
        sumX1Y += data[i].squareFootage * data[i].price;
        sumX2Y += data[i].numBedrooms * data[i].price;
        sumX3Y += data[i].numBathrooms * data[i].price;
        sumX4Y += ((data[i].location == location) ? 1 : 0) * data[i].price;
        sumX5Y += data[i].age * data[i].price;
    }
    double x1Mean = sumX1 / n, x2Mean = sumX2 / n, x3Mean = sumX3 / n, x5Mean = sumX5 / n;
    double yMean = sumY / n;
    double sX1 = 0, sX2 = 0, sX3 = 0, sX4 = 0, sX5 = 0, sY = 0, sX1Y = 0, sX2Y = 0, sX3Y = 0, sX4Y = 0, sX5Y = 0;
    for (int i = 0; i < n; i++) {
        sX1 += pow(data[i].squareFootage - x1Mean, 2);
        sX2 += pow(data[i].numBedrooms - x2Mean, 2);
        sX3 += pow(data[i].numBathrooms - x3Mean, 2);
        sX4 += pow(((data[i].location == location) ? 1 : 0) - ((sumX4 / n) * n), 2);
        sX5 += pow(data[i].age - x5Mean, 2);
        sY += pow(data[i].price - yMean, 2);
        sX1Y += (data[i].squareFootage - x1Mean) * (data[i].price - yMean);
        sX2Y += (data[i].numBedrooms - x2Mean) * (data[i].price - yMean);
        sX3Y += (data[i].numBathrooms - x3Mean) * (data[i].price - yMean);
        sX4Y += (((data[i].location == location) ? 1 : 0) - ((sumX4 / n) * n)) * (data[i].price - yMean);
        sX5Y += (data[i].age - x5Mean) * (data[i].price - yMean);
    }
    double beta1 = sX1Y / sX1;
    double beta2 = sX2Y / sX2;
    double beta3 = sX3Y / sX3;
    double beta4 = sX4Y / sX4;
    double beta5 = sX5Y / sX5;
    double alpha = yMean - (beta1 * x1Mean) - (beta2 * x2Mean) - (beta3 * x3Mean) - (beta4 * ((sumX4 / n) * n)) - (beta5 * x5Mean);
    double predictedPrice = (beta1 * squareFootage) + (beta2 * numBedrooms) + (beta3 * numBathrooms) + (beta4 * ((location == location) ? 1 : 0)) + (beta5 * age) + alpha;
    return predictedPrice;
}
int main() {
    vector<House> data = readData("houses.csv");
    normalizeFeatures(data);
    double predictedPrice = linearRegression(data, 2000, 3, 2, "New York", 10);
    cout << "Predicted price: " << predictedPrice << endl;
    return 0;
}
```
